-- BharatBol verified issue intake, July 2026
-- Run after phase7_geography.sql and phase10_stand_evidence.sql.
-- This is an evidence-led intake, not a quota. Every row below maps one
-- sourced public issue to one concrete demand. Add new rows only after source
-- review; do not create variants merely to fill a state or category.

begin;

create temporary table _issue_intake (
  id uuid primary key, state text not null, title text not null,
  description text not null, category text not null, source_label text not null,
  source_url text not null, source_published_on date not null
) on commit drop;

-- This table exists only for this SQL Editor session and is dropped on commit.
-- Enable RLS explicitly so automated schema checks do not flag the staging
-- data; the SQL Editor session owner can still use it to perform this ingest.
alter table _issue_intake enable row level security;


do $$
declare duplicate_title text;
begin
  select min(title) into duplicate_title
  from _issue_intake
  group by lower(title)
  having count(*) > 1
  limit 1;
  if duplicate_title is not null then raise exception 'Duplicate intake title: %', duplicate_title; end if;
  select s.title into duplicate_title from _issue_intake i join public.stands s on lower(s.title) = lower(i.title) and s.id <> i.id limit 1;
  if duplicate_title is not null then raise exception 'Existing stand has same title: %', duplicate_title; end if;
end $$;

select id,title,description,category,'live',source_label,source_url,source_published_on from _issue_intake
on conflict (id) do update set title=excluded.title, description=excluded.description, category=excluded.category,
  status=excluded.status, source_label=excluded.source_label, source_url=excluded.source_url, source_published_on=excluded.source_published_on;


commit;
